/**
 * AURA TIMEPIECES - HIGH RELIABILITY EMBEDDED ASSETS & MULTI-FALLBACK ENGINE
 * Guarantees zero broken images across all browsers, file:// protocols, local servers, and Shopify CDN.
 */
window.AURA_EMBEDDED_ASSETS = {'pagani_dive_poster.jpg': 'data:image/jpeg;base64,', 'benyar_lifestyle_poster.jpg': 'data:image/jpeg;base64,', 'naviforce_military_poster.jpg': 'data:image/jpeg;base64,', 'pagani_dive_macro.jpg': 'data:image/jpeg;base64,', 'benyar_blue_macro.jpg': 'data:image/jpeg;base64,', 'naviforce_green_macro.jpg': 'data:image/jpeg;base64,', 'lume_night_glow.jpg': 'data:image/jpeg;base64,', 'craftsmanship_atelier.jpg': 'data:image/jpeg;base64,', 'hero_watch_luxury.jpg': 'data:image/jpeg;base64,', 'royal_gold_watch.jpg': 'data:image/jpeg;base64,', 'titanium_diver.jpg': 'data:image/jpeg;base64,', 'carbon_chronograph.jpg': 'data:image/jpeg;base64,', 'celestial_moonphase.jpg': 'data:image/jpeg;base64,'};

// Universal Image Fallback Interceptor
(function() {
  function resolveFallback(imgElement) {
    if (!imgElement || imgElement.dataset.fallbackResolved === 'true') return;
    
    var currentSrc = imgElement.getAttribute('src') || '';
    // Extract base filename
    var filename = currentSrc.split('/').pop().split('?')[0].split('#')[0];
    
    if (window.AURA_EMBEDDED_ASSETS && window.AURA_EMBEDDED_ASSETS[filename]) {
      imgElement.dataset.fallbackResolved = 'true';
      imgElement.onerror = null;
      imgElement.src = window.AURA_EMBEDDED_ASSETS[filename];
      return;
    }
    
    // Try alternate relative paths
    var attempts = imgElement.dataset.errorAttempts ? parseInt(imgElement.dataset.errorAttempts) : 0;
    attempts++;
    imgElement.dataset.errorAttempts = attempts;
    
    if (attempts === 1) {
      imgElement.src = 'assets/images/' + filename;
    } else if (attempts === 2) {
      imgElement.src = 'assets/' + filename;
    } else if (attempts === 3) {
      imgElement.src = './' + filename;
    } else {
      imgElement.dataset.fallbackResolved = 'true';
      imgElement.onerror = null;
    }
  }

  // Global window error listener for IMG elements (captures early before DOMContentLoaded)
  window.addEventListener('error', function(event) {
    if (event.target && event.target.tagName === 'IMG') {
      resolveFallback(event.target);
    }
  }, true);

  // Proactive check on DOM load
  document.addEventListener('DOMContentLoaded', function() {
    var imgs = document.querySelectorAll('img');
    imgs.forEach(function(img) {
      if (img.complete && img.naturalWidth === 0) {
        resolveFallback(img);
      }
      img.addEventListener('error', function() {
        resolveFallback(img);
      });
    });
  });
})();
